//autogenerated:yes
//nolint:revive,govet,errcheck
package ardupilotmega_test

import (
	"testing"

	"github.com/stretchr/testify/require"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/ardupilotmega"
)

func TestEnum_CAMERA_STATUS_TYPES(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.CAMERA_STATUS_TYPES
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.CAMERA_STATUS_TYPE_HEARTBEAT.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.CAMERA_STATUS_TYPES
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.CAMERA_STATUS_TYPE_HEARTBEAT, dec)
	})
}
